    q("8", "في أي عام ميلادي خاض الهولندي ماركو فان باستن آخر مباراة رسمية له مع ميلان قبل أن تجبره إصابات الكاحل على الاعتزال المبكر؟", "1993", "1992", "1994", "1995"),
    q("8", "مع أي نادٍ هولندي كان يلعب رود خوليت وتوج معه بلقب الدوري قبل انضمامه التاريخي لميلان عام 1987 بصفقة قياسية؟", "آيندهوفن", "فاينورد", "هارلم", "أياكس أمستردام"),
    q("8", "ما هو النادي البرازيلي الذي دشن فيه الظاهرة رونالدو نازاريو مسيرته الاحترافية الأولى في الدرجة الممتازة عام 1993؟", "كروزيرو", "فلامنغو", "فاسكو دا غاما", "ساو باولو"),
    q("8", "في أي عام ميلادي قاد الحارس الأسطوري دينو زوف منتخب إيطاليا للفوز بكأس العالم كأكبر قائد يرفع الكأس بعمر 40 عاماً؟", "1982", "1978", "1980", "1986"),
    q("8", "ما هو النادي الأوروبي الذي اختتم فيه النجم الدنماركي مايكل لاودروب مسيرته الكروية الاحترافية عام 1998 محققاً الثنائية المحلية؟", "أياكس أمستردام", "ريال مدريد", "فيسيل كوبه", "بروندبي"),
    q("8", "في أي عام ميلادي توج النجم الإنجليزي كيفن كيغان بأول كرة ذهبية من كرتيه الذهبيتين المتتاليتين بقميص هامبورغ؟", "1978", "1976", "1977", "1979"),
    q("8", "مع أي نادٍ ياباني اختتم الهداف الإنجليزي غاري لينيكر مسيرته الاحترافية بين عامي 1992 و1994؟", "ناغويا غرامبوس", "يوكوهاما مارينوس", "أوراوا ريد دياموندز", "غامبا أوساكا"),
    q("8", "من أي نادٍ هولندي انضم النجم الهولندي دينيس بيركامب إلى إنتر ميلان الإيطالي في صيف 1993؟", "أياكس أمستردام", "آيندهوفن", "فاينورد", "أوتريخت"),
    q("8", "في أي عام ميلادي وقع الأسطورة البرازيلي روبرتو ريفيلينو لنادي الهلال السعودي في صفقة عالمية تاريخية للمنطقة؟", "1978", "1976", "1977", "1980"),
    q("8", "ما هو النادي الأرجنتيني الأول الذي لعب له الهداف غابرييل باتيستوتا في بدايات مسيرته الاحترافية عام 1988؟", "نيولز أولد بويز", "ريفر بليت", "بوكا جونيورز", "روساريو سنترال"),
    q("8", "في أي عام ميلادي لعب الأسطورة السير بوبي تشارلتون آخر مباراة رسمية له بقميص مانشستر يونايتد؟", "1973", "1970", "1971", "1975"),
    q("8", "مع أي نادٍ إسباني لعب الهولندي فرانك ريكارد معاراً خلال موسم 1987-1988 قبل انضمامه الذهبي لنادي ميلان؟", "ريال سرقسطة", "إسبانيول", "سيلتا فيغو", "سبورتينغ خيخون"),
    q("8", "في أي عام ميلادي توج المهاجم الألماني كارل هاينز رومينيغه بأول جائزة كرة ذهبية له مع بايرن ميونخ؟", "1980", "1978", "1979", "1981"),
    q("8", "مع أي نادٍ إيطالي أنهى الهداف الألماني أوليفر بيرهوف مسيرته الكروية الاحترافية في موسم 2002-2003 مسجلاً هاتريك في مباراته الأخيرة؟", "كييفو فيرونا", "أودينيزي", "ميلان", "أسكولي"),
    q("8", "مع أي نادٍ ألماني بدأ الهداف يورغن كلينسمان مسيرته الاحترافية في الدرجة الثانية عام 1981؟", "شتوتغارت كيكرز", "شتوتغارت", "أولم 1846", "كارلسروه"),
    q("8", "في أي عام ميلادي قاد باولو روسي إيطاليا للفوز بكأس العالم وتوج هدافاً للبطولة بستة أهداف ونال الكرة الذهبية؟", "1982", "1978", "1980", "1984"),
    q("8", "ما هو النادي الأمريكي الذي اختتم فيه الأسطورة البلغاري خريستو ستويتشكوف مسيرته الاحترافية كلاعب عام 2003؟", "دي سي يونايتد", "شيكاغو فاير", "نيويورك متروستارز", "دالاس بيرن"),
    q("8", "في أي عام ميلادي توج الدنماركي ألان سيمونسن بجائزة الكرة الذهبية أثناء لعبه مع بوروسيا مونشنغلادباخ؟", "1977", "1975", "1976", "1978"),
    q("8", "ما هو النادي الروماني الذي بدأ فيه الأسطورة جورجي هاجي مسيرته الاحترافية في الدوري الروماني الممتاز عام 1982؟", "فارول كونستانتسا", "ستيوا بوخارست", "دينامو بوخارست", "سبورتول ستودينتيسك"),
    q("8", "في أي عام ميلادي توج الأسطورة الإنجليزي السير ستانلي ماثيوز بأول جائزة كرة ذهبية في تاريخ مجلة فرانس فوتبول في سن الـ 41؟", "1956", "1954", "1955", "1957"),
  ];

  // ==============================================================
  // VALIDATION CHECKS
  // ==============================================================
  print("Total questions loaded: ${questions.length}");
  assert(questions.length == 300, "Must be exactly 300 questions, got ${questions.length}");

  final countsByLevel = <String, int>{};
  final questionsSet = <String>{};
  
  for (int i = 0; i < questions.length; i++) {
    final item = questions[i];
    final lvl = item["Level"] as String;
    final qText = item["Q"] as String;
    final r = item["R"] as String;
    final w1 = item["W1"] as String;
    final w2 = item["W2"] as String;
    final w3 = item["W3"] as String;
    final cat = item["Category"] as String;

    countsByLevel[lvl] = (countsByLevel[lvl] ?? 0) + 1;

    // Check Question formatting
    if (!qText.endsWith("؟")) {
      throw Exception("Question #$i does not end with '؟': $qText");
    }

    // Check Question uniqueness
    if (questionsSet.contains(qText)) {
      throw Exception("Duplicate question found: $qText");
    }
    questionsSet.add(qText);

    // Check options uniqueness within question
    final options = [r, w1, w2, w3];
    final uniqueOptions = options.toSet();
    if (uniqueOptions.length != 4) {
      throw Exception("Duplicate options in question #$i ($qText): $options");
    }

    // Check Category
    if (cat != "لاعبين كرة قدم") {
      throw Exception("Invalid category in question #$i: $cat");
    }
  }

  print("Counts by level:");
  countsByLevel.keys.toList()..sort()..forEach((k) => print("  Level $k: ${countsByLevel[k]}"));

  // Check expected level counts
  final expected = {
    "0": 34,
    "1": 33,
    "2": 33,
    "4": 33,
    "5": 33,
    "6": 34,
    "3": 33,
    "7": 33,
    "8": 34,
  };

  expected.forEach((lvl, expectedCount) {
    final actual = countsByLevel[lvl] ?? 0;
    if (actual != expectedCount) {
      throw Exception("Level $lvl count mismatch: expected $expectedCount, got $actual");
    }
  });

  // Tiers check
  final tier0 = (countsByLevel["0"] ?? 0) + (countsByLevel["1"] ?? 0) + (countsByLevel["2"] ?? 0);
  final tier1 = (countsByLevel["4"] ?? 0) + (countsByLevel["5"] ?? 0) + (countsByLevel["6"] ?? 0);
  final tier2 = (countsByLevel["3"] ?? 0) + (countsByLevel["7"] ?? 0) + (countsByLevel["8"] ?? 0);
  print("Tier 0 total: $tier0 (expected 100)");
  print("Tier 1 total: $tier1 (expected 100)");
  print("Tier 2 total: $tier2 (expected 100)");

  assert(tier0 == 100);
  assert(tier1 == 100);
  assert(tier2 == 100);

  // Additional quality audits:
  int leakCount = 0;
  for (int i = 0; i < questions.length; i++) {
    final qText = questions[i]["Q"] as String;
    final r = questions[i]["R"] as String;
    // Check if R appears inside Q
    if (qText.contains(r)) {
      print("Potential leak in #$i: Q='$qText' contains R='$r'");
      leakCount++;
    }
  }
  print("Leak check complete: $leakCount potential leaks found.");

  // Write JSON to file
  final jsonStr = JsonEncoder.withIndent("  ").convert(questions);
  final outFile = File("assets/questions_career_300.json");
  outFile.writeAsStringSync(jsonStr, encoding: utf8);
  print("Successfully saved 300 questions to ${outFile.path}");
}
